import { SwipeableCardStack } from "@nativecn/ui/premium/mobile/swipeable-card-stack";

export default function App() {
  const cards = [
    { id: "1", title: "Card One", color: "#a855f7" },
    { id: "2", title: "Card Two", color: "#3b82f6" },
    { id: "3", title: "Card Three", color: "#10b981" },
  ];
  return (
    <SwipeableCardStack
      data={cards}
      renderCard={(item) => <Text style={{ color: "white" }}>{item.title}</Text>}
      onSwipeLeft={(item) => console.log("Skipped:", item.id)}
      onSwipeRight={(item) => console.log("Liked:", item.id)}
    />
  );
}
